const dependentVowels = new Set([
  "್", "ಾ", "ಿ", "ೀ", "ು", "ೂ", "ೃ", "ೆ", "ೇ", "ೈ", "ೊ", "ೋ", "ೌ"
]);

export function unicodeToNudi(knUnicode: string): string {
    if (!knUnicode) return "";
    const words = knUnicode.split(" ");
    const outWords = [];
    for (const word of words) {
        outWords.push(processWord(word));
    }
    return outWords.join(" ");
}

function processWord(word: string): string {
    let chars = Array.from(word);
    
    // First pass: reorder Vatthu and Dependent Vowels
    for (let zz = 1; zz < chars.length; zz++) {
        if (chars[zz] === '್') {
            const remaining = chars.length - zz;
            if (remaining <= 1) {
                // Word ending with ್, do nothing
            } else if (remaining === 2) {
                // No dependent vowel after consonant
                const nextChar = chars[zz + 1];
                if (vattaksharagalu[nextChar]) {
                    chars[zz] = vattaksharagalu[nextChar];
                    chars.splice(zz + 1, 1);
                }
            } else {
                const nextChar = chars[zz + 1];
                const dv = chars[zz + 2];
                if (dependentVowels.has(dv) && vattaksharagalu[nextChar]) {
                    chars[zz] = dv;
                    chars[zz + 1] = vattaksharagalu[nextChar];
                    chars.splice(zz + 2, 1);
                } else if (vattaksharagalu[nextChar]) {
                    chars[zz] = vattaksharagalu[nextChar];
                    chars.splice(zz + 1, 1);
                }
            }
        }
    }
    
    // Second pass: Map to ASCII
    let resultText = chars.join("");
    let op = "";
    let i = 0;
    
    while (i < resultText.length) {
        let maxLen = Math.min(4, resultText.length - i);
        let matchFound = false;
        
        for (let j = maxLen; j > 0; j--) {
            const t = resultText.substring(i, i + j);
            if (mapping[t]) {
                op += mapping[t];
                i += j;
                matchFound = true;
                break;
            }
        }
        
        if (!matchFound) {
            op += resultText[i];
            i++;
        }
    }
    
    return op;
}

const reverseMap: Record<string, string> = {};
for (const [key, value] of Object.entries(mapping)) {
    if (value && key && !reverseMap[value]) {
        reverseMap[value] = key;
    }
}
const reverseKeys = Object.keys(reverseMap).sort((a,b)=>b.length-a.length);

const reverseVatthu: Record<string, string> = {};
for (const [key, value] of Object.entries(vattaksharagalu)) {
    if (value && key) reverseVatthu[value] = key;
}

export function nudiToUnicode(knAscii: string): string {
    if (!knAscii) return "";

    let words = knAscii.split(" ");
    let outWords = [];

    for (const word of words) {
        let currentWord = word;

        let res = "";
        let i = 0;
        let unicodeTokens = [];
        while (i < currentWord.length) {
            let matched = false;
            for (const key of reverseKeys) {
                if (currentWord.startsWith(key, i)) {
                    unicodeTokens.push({ type: 'normal', val: reverseMap[key] });
                    i += key.length;
                    matched = true;
                    break;
                }
            }
            if(!matched){
               const char = currentWord[i];
               if(reverseVatthu[char]) {
                   unicodeTokens.push({ type: 'vatthu', val: reverseVatthu[char] });
               } else {
                   unicodeTokens.push({ type: 'normal', val: char });
               }
               i++;
            }
        }
        
        let chars = [];
        for(let token of unicodeTokens) {
            if (token.type === 'vatthu') {
                chars.push('್');
                chars.push(token.val);
                chars.push('_VATTU_MARKER_'); 
            } else {
                chars.push(...Array.from(token.val));
            }
        }

        for (let zz = 0; zz < chars.length; zz++) {
           if (chars[zz] === '_VATTU_MARKER_') {
               if (zz >= 3 && chars[zz-2] === '್') {
                  const dv: string = chars[zz-3];
                  if (dependentVowels.has(dv)) {
                      chars[zz-3] = chars[zz-2];
                      chars[zz-2] = chars[zz-1];
                      chars[zz-1] = dv;
                  }
               }
           }
        }
        
        outWords.push(chars.filter(c => c !== '_VATTU_MARKER_').join(""));
    }
    return outWords.join(" ");
}
